#include <iostream>
#include <fstream>

int probar(int a, int b) {
    std::ofstream salida{"datos_recarga.txt"};
    if (!salida) {
        std::cout << "Error apertura de salida";
        return 1;
    }
    salida << a << ' ' << b;
    salida.close();
    if (!salida) {
        std::cout << "Error escritura";
        return 1;
    }
    std::ifstream entrada{"datos_recarga.txt"};
    if (!entrada) {
        std::cout << "Error apertura de entrada";
        return 1;
    }
    int primero{0};
    int segundo{0};
    if (!(entrada >> primero >> segundo)) {
        std::cout << "Formato invalido";
        return 1;
    }
    std::cout << "Total=" << primero + segundo << "\n";
    return 0;
}

int main() {
    if (probar(4, 7) != 0) return 1;
    if (probar(0, 6) != 0) return 1;
    return 0;
}
